package com.hbm.tileentity.machine.rbmk;

import dev.golem.core.data.Tags;
 import com.hbm.api.energymk2.IEnergyReceiverMK2; import com.hbm.api.redstoneoverradio.IRORValueProvider; import com.hbm.interfaces.IControlReceiver; import com.hbm.handler.neutron.RBMKNeutronHandler.RBMKType; import dev.golem.core.data.*; import net.minecraft.core.*; import net.minecraft.nbt.CompoundTag; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.util.Mth; import net.minecraft.world.level.block.entity.BlockEntityType; import net.minecraft.world.level.block.state.BlockState;
/** Control motion intentionally charges once per moving tick, not per distance travelled. */
 public abstract class BlockEntityRBMKControl extends BlockEntityRBMKBase implements IControlReceiver, IEnergyReceiverMK2, IRORValueProvider {
 public static final double speed=.00277D; public static final long consumption=5000,maxPower=consumption*10; public double lastLevel,level,targetLevel; public boolean hasPower; public long power;
 protected BlockEntityRBMKControl(BlockEntityType<?> t,BlockPos p,BlockState s){super(t,p,s,0);} public boolean isPowered(){return getBlockState().is(com.hbm.blocks.machine.rbmk.ModRBMKBlocks.rbmk_control_reasim.get())||getBlockState().is(com.hbm.blocks.machine.rbmk.ModRBMKBlocks.rbmk_control_reasim_auto.get());}
 @Override public long getPower(){return power;} @Override public void setPower(long p){power=p;} @Override public long getMaxPower(){return isPowered()?maxPower:0;} @Override public boolean canConnect(com.hbm.lib.ForgeDirection d){return isPowered()&&d==com.hbm.lib.ForgeDirection.DOWN;} @Override public ConnectionPriority getPriority(){return ConnectionPriority.LOW;} @Override public boolean isLidRemovable(){return false;} @Override public void tickClient(){lastLevel=level;}
 @Override public void tickServer(){hasPower=!isPowered()||power>=consumption;lastLevel=level;if(hasPower){double speed=speed();if(level<targetLevel){level+=speed*RBMKDials.getControlSpeed(getLevel());if(level>targetLevel)level=targetLevel;}if(level>targetLevel){level-=speed*RBMKDials.getControlSpeed(getLevel());if(level<targetLevel)level=targetLevel;}if(isPowered()&&level!=lastLevel)power-=consumption;}super.tickServer();}
  public double speed(){return getBlockState().getBlock() instanceof com.hbm.blocks.machine.rbmk.RBMKControl control?BlockEntityRBMKControl.speed*control.speed:BlockEntityRBMKControl.speed;} public void setTarget(double target){targetLevel=Mth.clamp(target,0D,1D);} public double getMult(){return level;} @Override public int trackingRange(){return 100;} @Override public RBMKType getRBMKType(){return RBMKType.CONTROL_ROD;} @Override public boolean hasPermission(net.minecraft.world.entity.player.Player p){if(p.containerMenu instanceof com.hbm.inventory.container.MenuRBMKControl manual)return manual.blockEntity()==this&&manual.stillValid(p);if(p.containerMenu instanceof com.hbm.inventory.container.MenuRBMKControlAuto automatic)return automatic.blockEntity()==this&&automatic.stillValid(p);return false;} @Override public void receiveControl(CompoundTag data){if(Tags.hasDouble(data,"level"))setTarget(Tags.getDoubleOr(data,"level",0D));}
 @Override public RBMKColumn getConsoleData(){RBMKColumn.ControlColumn c=(RBMKColumn.ControlColumn)super.getConsoleData();c.level=level;return c;} @Override protected void loadData(DataIn i){super.loadData(i);level=i.getDoubleOr("level",level);targetLevel=i.getDoubleOr("targetLevel",targetLevel);}@Override protected void saveData(DataOut o){super.saveData(o);o.putDouble("level",level);o.putDouble("targetLevel",targetLevel);}@Override public void serialize(RegistryFriendlyByteBuf b){super.serialize(b);b.writeDouble(level);b.writeDouble(targetLevel);b.writeLong(power);b.writeBoolean(hasPower);}@Override public void deserialize(RegistryFriendlyByteBuf b){super.deserialize(b);level=b.readDouble();targetLevel=b.readDouble();power=b.readLong();hasPower=b.readBoolean();}
  @Override public String[] getFunctionInfo(){return new String[]{PREFIX_VALUE+"extraction"};}
  @Override public String provideRORValue(String name){return (PREFIX_VALUE+"extraction").equals(name)?""+(int)(level*100):null;}
 }
